solution:
def fare(km, age, female=False):
    price = 20 + 2 * km
    if age >= 60:
        off = 50 if female else 40
        price = price * (100 - off) // 100
    return price

alt:
def fare(km, age, female=False):
    price = 20 + 2 * km
    if age < 60:
        return price
    if female:
        return price // 2
    return price * 60 // 100
